```kotlin
import java.math.BigInteger
import java.util.*

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextLong()
    var k = scanner.nextLong()

    val luckyNumbers = mutableListOf<Long>()
    val queue = ArrayDeque<Long>()
    queue.add(4)
    queue.add(7)
    while (queue.isNotEmpty()) {
        val x = queue.removeFirst()
        if (x > n) continue
        luckyNumbers.add(x)
        queue.add(x * 10 + 4)
        queue.add(x * 10 + 7)
    }
    luckyNumbers.sort()

    val isLucky = BooleanArray(n.toInt() + 1)
    for (l in luckyNumbers) {
        if (l <= n) isLucky[l.toInt()] = true
    }

    val maxM = 20
    val fact = LongArray(maxM + 1)
    fact[0] = 1
    for (i in 1..maxM) {
        if (fact[i - 1] > Long.MAX_VALUE / i) {
            fact[i] = Long.MAX_VALUE
        } else {
            fact[i] = fact[i - 1] * i
        }
    }

    var m = 0
    while (m <= maxM && fact[m] < k) {
        m++
    }

    if (m > n) {
        println(-1)
        return
    }

    var ans = 0
    for (l in luckyNumbers) {
        if (l <= n - m) ans++
    }

    val available = mutableListOf<Long>()
    for (i in (n - m + 1)..n) {
        available.add(i)
    }

    var currentK = k - 1
    for (i in 0 until m) {
        val pos = n - m + 1 + i
        val remaining = m - i - 1
        val f = if (remaining >= 0) fact[remaining] else 1
        val index = (currentK / f).toInt()
        val val = available.removeAt(index)
        currentK %= f
        if (isLucky[pos.toInt()] && isLucky[val.toInt()]) {
            ans++
        }
    }

    println(ans)
}
